layout = {
	name: "Grounded Skybox",
	width: 300,
	elements: [
		{ name: 'Texture', inputType: 'Texture' },
		{ name: 'Height', inputType: 'Number' },
		{ name: 'Radius', inputType: 'Number' }
	]
};

function getGroundedSkybox() {

	async function load() {

		const { GroundedSkybox } = await import( 'three/addons/objects/GroundedSkybox.js' );

		local.set( 'GroundedSkybox', GroundedSkybox );

		refresh();

	}

	load();

	return null;

}

function main() {

	const GroundedSkybox = local.get( 'GroundedSkybox', getGroundedSkybox );
	const texture = parameters.get( 'Texture' );
	const height = parameters.get( 'Height' );
	const radius = parameters.get( 'Radius' );

	if ( GroundedSkybox !== null && texture !== null ) {

		const grounded = new GroundedSkybox( texture, height, radius );
		grounded.position.y = height - 0.01;


		return grounded;

	}

}

