// Addition Node Example
// THREE and TSL (Three.js Shading Language) namespaces are available!
// Enjoy! :)

// layout must be the first variable.

layout = {
	name: "GLTF Loader",
	width: 300,
	outputType: 'Object3D',
	elements: [
		{ name: 'File', inputType: 'URL' }
	]
};

function loadFile() {

	const url = parameters.get( 'File' );

	async function load() {

		const { DRACOLoader } = await import( 'three/addons/loaders/DRACOLoader.js' );
		const { GLTFLoader } = await import( 'three/addons/loaders/GLTFLoader.js' );

		const dracoLoader = new DRACOLoader();
		dracoLoader.setDecoderPath( '../examples/jsm/libs/draco/gltf/' );

		const loader = new GLTFLoader();
		loader.setDRACOLoader( dracoLoader );

		const model = await loader.loadAsync( url );

		local.set( url, model.scene );

		refresh();

	}

	load();

	return null;

}

function main() {

	const url = parameters.get( 'File' );
	const result = url ? local.get( url, loadFile ) : null;

	if ( result ) result.scale.setScalar( 3 );

	return result;

}

