layout = {
	name: "Unreal Bloom",
	width: 300,
	elements: [
		{ name: 'strength', inputType: 'Number', value: 1 },
		{ name: 'threshold', inputType: 'Number' },
		{ name: 'radius', inputType: 'Number' }
	]
};

function loadRenderPass() {

	async function load() {

		const { UnrealBloomPass  } = await import( 'three/addons/postprocessing/UnrealBloomPass.js' );

		const bloomPass = new UnrealBloomPass( new THREE.Vector2( window.innerWidth, window.innerHeight ), 1.5, 0.4, 0.85 );

		local.set( 'Pass', bloomPass );

		refresh();

	}

	load();

	return null;

}

function main() {

    const renderPass = local.get( 'Pass', loadRenderPass )

    if ( renderPass ) {

		renderPass.strength = parameters.get( 'strength' );
		renderPass.threshold = parameters.get( 'threshold' );
		renderPass.radius = parameters.get( 'radius' );

    }

    return renderPass;

}

